class ReportService {
  private _client?: HeavyClient;
  get client() {
    if (!this._client) {
      this._client = new HeavyClient();
    }
    return this._client;
  }
}

class Cache {
  private _data?: Data;
  get data() {
    if (!this._data) {
      this._data = fetchDataFromNetwork();
    }
    return this._data;
  }
}

// Version A
class OrderProcessorA {
  private _client?: PaymentClient;
  private get client() {
    if (!this._client) this._client = new PaymentClient();
    return this._client;
  }
  process() { this.client.charge(); }
}

// Version B
class OrderProcessorB {
  constructor(private clientProvider: () => PaymentClient) {}
  process() { const client = this.clientProvider(); client.charge(); }
}
